#if UNITY_EDITOR
using System.IO;
using UnityEditor;
using UnityEngine;
public static class InGameUIPortraitAssets
{
 public const string Folder="Assets/UIImage/IngameUI/Profiles/";
 static Sprite Import(string path){AssetDatabase.ImportAsset(path);var i=(TextureImporter)AssetImporter.GetAtPath(path);i.textureType=TextureImporterType.Sprite;i.spriteImportMode=SpriteImportMode.Single;i.alphaIsTransparency=true;i.mipmapEnabled=false;i.textureCompression=TextureImporterCompression.Uncompressed;i.SaveAndReimport();return AssetDatabase.LoadAssetAtPath<Sprite>(path);}
 public static void Prepare(){var sheet=new Texture2D(2,2,TextureFormat.RGBA32,false);sheet.LoadImage(File.ReadAllBytes(Folder+"CharacterExpressions.png"));int w=sheet.width/2,h=sheet.height/2;string[] names={"Normal","Hit","Success","Hurt"};for(int i=0;i<4;i++){var crop=new Texture2D(w,h,TextureFormat.RGBA32,false);crop.SetPixels(sheet.GetPixels(i%2*w,(i<2?1:0)*h,w,h));crop.Apply();string p=Folder+names[i]+".png";File.WriteAllBytes(p,crop.EncodeToPNG());Object.DestroyImmediate(crop);Import(p);}Object.DestroyImmediate(sheet);
 const int size=256;var circle=new Texture2D(size,size,TextureFormat.RGBA32,false);var pixels=new Color[size*size];for(int y=0;y<size;y++)for(int x=0;x<size;x++){float d=Vector2.Distance(new Vector2(x+.5f,y+.5f),new Vector2(size*.5f,size*.5f));pixels[y*size+x]=new Color(1,1,1,Mathf.Clamp01(size*.5f-d));}circle.SetPixels(pixels);circle.Apply();string path=Folder+"CooldownCircle.png";File.WriteAllBytes(path,circle.EncodeToPNG());Object.DestroyImmediate(circle);Import(path);}
 public static void Apply(Transform canvas){var vitals=canvas.Find("HUD/Vitals");var profile=vitals.Find("Profile");var maskRect=vitals.Find("ProfileMask") as RectTransform;if(maskRect==null){maskRect=(RectTransform)new GameObject("ProfileMask",typeof(RectTransform)).transform;maskRect.SetParent(vitals,false);maskRect.gameObject.layer=5;}maskRect.anchorMin=maskRect.anchorMax=new Vector2(.5f,.5f);maskRect.sizeDelta=new Vector2(90,90);maskRect.anchoredPosition=new Vector2(98.29944f,-101);var image=maskRect.GetComponent<UnityEngine.UI.Image>()??maskRect.gameObject.AddComponent<UnityEngine.UI.Image>();image.sprite=AssetDatabase.LoadAssetAtPath<Sprite>(Folder+"CooldownCircle.png");image.raycastTarget=false;var mask=maskRect.GetComponent<UnityEngine.UI.Mask>()??maskRect.gameObject.AddComponent<UnityEngine.UI.Mask>();mask.showMaskGraphic=false;if(profile==null)profile=maskRect.Find("Profile");profile.SetParent(maskRect,false);var rect=(RectTransform)profile;rect.anchorMin=rect.anchorMax=new Vector2(.5f,.5f);rect.sizeDelta=new Vector2(110,110);rect.anchoredPosition=new Vector2(0,-8);var view=vitals.GetComponent<PlayerProfileUI>()??vitals.gameObject.AddComponent<PlayerProfileUI>();view.Portrait=profile.GetComponent<UnityEngine.UI.Image>();view.Portrait.color=Color.white;view.Portrait.enabled=true;view.Normal=AssetDatabase.LoadAssetAtPath<Sprite>(Folder+"Normal.png");view.Hit=AssetDatabase.LoadAssetAtPath<Sprite>(Folder+"Hit.png");view.Success=AssetDatabase.LoadAssetAtPath<Sprite>(Folder+"Success.png");view.Hurt=AssetDatabase.LoadAssetAtPath<Sprite>(Folder+"Hurt.png");view.Portrait.sprite=view.Normal;vitals.Find("ProfileFrame").SetAsLastSibling();maskRect.SetSiblingIndex(vitals.Find("ProfileFrame").GetSiblingIndex()-1);foreach(var button in canvas.GetComponentsInChildren<SkillButton>(true)){var cd=button.CooldownImage;var icon=(RectTransform)button.transform.Find("Icon");cd.rectTransform.sizeDelta=icon.sizeDelta;cd.rectTransform.anchoredPosition=icon.anchoredPosition;cd.sprite=image.sprite;cd.color=new Color(0,0,0,.65f);cd.type=UnityEngine.UI.Image.Type.Filled;cd.fillMethod=UnityEngine.UI.Image.FillMethod.Radial360;cd.fillOrigin=(int)UnityEngine.UI.Image.Origin360.Top;cd.fillClockwise=true;cd.raycastTarget=false;cd.fillAmount=0;cd.enabled=false;}}
}
